SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND COLUMN_NAME IN ('DOCUMENTO_IDENTIDAD_UNICA','VERIFICACION_CP_JSON','REFERENCIAS_CP_JSON');
